<?php
declare(strict_types=1);
function vh(mixed $v): string { return htmlspecialchars((string) $v, ENT_QUOTES | ENT_SUBSTITUTE, 'UTF-8'); }
$canApprove = (bool) ($user['valider_devis'] ?? false) || (bool) ($user['gestion_utilisateur'] ?? false);
$hasProfileSignature = !empty($user['signature']) && is_file(APP_ROOT . '/' . $user['signature']);
?>
<!doctype html><html lang="fr"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Validation des FEB · FIDEST</title><link href="https://cdn.jsdelivr.net/npm/bootstrap@5.3.2/dist/css/bootstrap.min.css" rel="stylesheet"><link href="https://cdnjs.cloudflare.com/ajax/libs/font-awesome/6.5.0/css/all.min.css" rel="stylesheet"><link rel="stylesheet" href="css/style.css"><link rel="stylesheet" href="css/modules.css"><style>.validation-shell{max-width:1180px}.validation-hero{margin-bottom:20px;padding:27px;border-radius:22px;color:#fff;background:linear-gradient(120deg,var(--brand-primary),#3a3e77)}.validation-hero h1{color:#fff!important;margin:0}.validation-hero p{margin:7px 0 0;color:#ffffffb8}.feb-validation-card{margin-bottom:16px;padding:20px;background:#fff;border:1px solid var(--brand-border);border-radius:18px}.feb-validation-card header{display:flex;justify-content:space-between;gap:18px}.feb-meta{color:#727588;font-size:.84rem}.signature-choice{display:flex;gap:14px;flex-wrap:wrap;margin:14px 0 8px}.signature-pad-wrap{display:none;margin-top:10px}.signature-pad-wrap.is-active{display:block}.feb-signature-pad{width:100%;height:130px;background:#fff;border:2px dashed #aeb1c4;border-radius:12px;touch-action:none}.action-row{display:flex;gap:8px;align-items:flex-end;flex-wrap:wrap}.reason{flex:1 1 280px}.status-pill{height:max-content}.sign-help{font-size:.78rem;color:#727588}@media(max-width:650px){.feb-validation-card header{flex-direction:column}}</style></head><body class="module-page"><?php include APP_ROOT . '/partials/navbar.php'; ?><main class="container validation-shell"><section class="validation-hero"><h1><i class="fa-solid fa-file-signature me-2 text-warning"></i>Validation des FEB</h1><p>Analysez, approuvez ou rejetez les fiches avec votre signature de profil ou une signature manuscrite ponctuelle.</p></section><?php if ($flash): ?><div class="alert alert-<?= vh($flash['type'] ?? 'info') ?>"><?= vh($flash['message'] ?? '') ?></div><?php endif; ?>
<?php $pending=false; foreach ($rows as $row): if (!in_array($row['statut'], ['a_analyser','analyse'], true)) continue; $pending=true; $isAnalysis=$row['statut']==='a_analyser'; ?><article class="feb-validation-card"><header><div><strong><?= vh($row['numero_feb']) ?></strong><div class="feb-meta"><?= vh($row['nom_client']) ?> · <?= vh($row['numero_bc']) ?> · <?= number_format((float)$row['montant_demande'],0,',',' ') ?> FCFA</div><div class="feb-meta">Établi par <?= vh($row['prepared_name'] ?: '—') ?> · disponible le <?= vh(date('d/m/Y',strtotime((string)$row['date_disponibilite']))) ?></div></div><span class="badge text-bg-warning status-pill"><?= vh($isAnalysis?'À analyser':'Analysée, à approuver') ?></span></header><form method="post" action="request/validate_feb.php" class="feb-validation-form"><input type="hidden" name="csrf" value="<?= vh($csrf) ?>"><input type="hidden" name="feb_id" value="<?= (int)$row['id'] ?>"><input type="hidden" name="return_to" value="validation"><div class="signature-choice"><label><input type="radio" name="signature_source" value="profile" checked> Utiliser ma signature de profil</label><label><input type="radio" name="signature_source" value="pad"> Signer maintenant sur le pad</label></div><div class="sign-help"><?= $hasProfileSignature ? 'Votre signature de profil sera copiée sur cette FEB.' : 'Aucune signature de profil disponible : utilisez le pad ou enregistrez-en une dans votre profil.' ?></div><div class="signature-pad-wrap"><canvas class="feb-signature-pad"></canvas><input type="hidden" name="signature_data"><button class="btn btn-sm btn-outline-secondary mt-2 clear-pad" type="button"><i class="fa-solid fa-eraser"></i> Effacer</button></div><div class="action-row mt-3"><?php if($isAnalysis): ?><button class="btn btn-primary" name="action" value="analyze"><i class="fa-solid fa-magnifying-glass-check me-1"></i>Analyser et signer</button><?php elseif($canApprove): ?><button class="btn btn-success" name="action" value="approve"><i class="fa-solid fa-check-double me-1"></i>Approuver et signer</button><?php else: ?><span class="text-muted small">Vous n’avez pas le droit d’approbation.</span><?php endif; ?><div class="reason"><label class="form-label small mb-1">Motif de rejet</label><input class="form-control form-control-sm" name="reason" placeholder="Obligatoire en cas de rejet"></div><button class="btn btn-outline-danger" name="action" value="reject"><i class="fa-solid fa-xmark me-1"></i>Rejeter et signer</button><a class="btn btn-sm btn-outline-primary" target="_blank" href="request/export_feb_pdf.php?id=<?= (int)$row['id'] ?>"><i class="fa-regular fa-eye"></i> Voir</a></div></form></article><?php endforeach; if (!$pending): ?><section class="feb-validation-card text-center py-5 text-muted"><i class="fa-solid fa-circle-check fa-2x mb-3 d-block text-success"></i>Aucune FEB en attente de validation.</section><?php endif; ?></main><script>document.querySelectorAll('.feb-validation-form').forEach(form=>{const pad=form.querySelector('.feb-signature-pad'),box=form.querySelector('.signature-pad-wrap'),data=form.querySelector('[name=signature_data]'),ctx=pad.getContext('2d');let drawing=false,dirty=false;function resize(){const r=Math.max(devicePixelRatio||1,1),b=pad.getBoundingClientRect();pad.width=Math.round(b.width*r);pad.height=Math.round(b.height*r);ctx.setTransform(r,0,0,r,0,0);ctx.lineWidth=2.2;ctx.lineCap='round';ctx.strokeStyle='#172044'}function point(e){const b=pad.getBoundingClientRect();return{x:e.clientX-b.left,y:e.clientY-b.top}}resize();form.querySelectorAll('[name=signature_source]').forEach(input=>input.addEventListener('change',()=>box.classList.toggle('is-active',form.querySelector('[value=pad]').checked)));pad.addEventListener('pointerdown',e=>{e.preventDefault();drawing=true;const p=point(e);ctx.beginPath();ctx.moveTo(p.x,p.y);pad.setPointerCapture(e.pointerId)});pad.addEventListener('pointermove',e=>{if(!drawing)return;const p=point(e);ctx.lineTo(p.x,p.y);ctx.stroke();dirty=true});pad.addEventListener('pointerup',()=>{drawing=false;if(dirty)data.value=pad.toDataURL('image/png')});form.querySelector('.clear-pad').addEventListener('click',()=>{ctx.clearRect(0,0,pad.width,pad.height);data.value='';dirty=false});form.addEventListener('submit',e=>{if(form.querySelector('[value=pad]').checked&&!data.value){e.preventDefault();alert('Dessinez votre signature avant de valider.')}})});</script></body></html>
